package hu.synostream.android;
import android.content.*;import android.net.Uri;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.io.*;
@RunWith(AndroidJUnit4.class) public class Android058Test {
 final Android050FlowTest f=new Android050FlowTest();
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{UiLocale.save(f.context,"hu");f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 @Test public void actualTranslationsMatchThirtySixFrozenGoldenBytes()throws Exception{JSONArray samples;try(InputStream input=f.instrumentation.getContext().getAssets().open("ui058-golden.json")){samples=new JSONArray(new String(input.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}assertEquals(36,samples.length());for(int i=0;i<samples.length();i++){JSONObject sample=samples.getJSONObject(i);UiLocale.save(f.context,sample.getString("language"));assertArrayEquals(sample.getString("input"),sample.getString("expected").getBytes(java.nio.charset.StandardCharsets.UTF_8),UiText.message(f.context,sample.getString("input")).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 @Test public void newInstallLanguageIsNotSavedAndDoesNotChangeAfterLibrarySeeding(){String name="locale-058-fixture";SharedPreferences prefs=f.context.getSharedPreferences(name,Context.MODE_PRIVATE);assertTrue(prefs.edit().clear().commit());Context isolated=new ContextWrapper(f.context){@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return prefs;}};try{UiLocale.initialize(isolated);String expected=UiLanguage.initial(false,android.content.res.Resources.getSystem().getConfiguration().getLocales().get(0).getLanguage());assertEquals(expected,UiLocale.language(isolated));assertFalse(prefs.contains("ui_language"));assertTrue(prefs.edit().putString("libraries","[]").commit());assertEquals(expected,UiLocale.language(isolated));assertFalse(prefs.contains("ui_language"));assertTrue(UiLocale.save(isolated,"hu"));assertEquals("hu",UiLocale.language(isolated));}finally{prefs.edit().clear().commit();}}
 @Test public void legacyInstallKeepsHungarianUntilExplicitSelection(){SharedPreferences prefs=f.context.getSharedPreferences("locale-058-legacy-fixture",Context.MODE_PRIVATE);assertTrue(prefs.edit().clear().putString("libraries","[]").commit());Context isolated=new ContextWrapper(f.context){@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return prefs;}};try{assertEquals("hu",UiLocale.language(isolated));assertFalse(prefs.contains("ui_language"));assertTrue(UiLocale.save(isolated,"en"));assertEquals("en",UiLocale.language(isolated));}finally{prefs.edit().clear().commit();}}
 @Test public void fileSchemeCannotBecomePendingImport()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->activity.onNewIntent(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("file:///synthetic-private-file.torrent"),"application/x-bittorrent")));assertNull(f.app.externalTorrentUri);assertNull(f.app.torrentDraft.bytes);assertEquals(0,n.prepares);assertEquals(0,n.starts);Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("file:///synthetic.torrent"),"application/x-bittorrent");assertFalse(f.context.getPackageManager().queryIntentActivities(view,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY).stream().anyMatch(info->f.pkg.equals(info.activityInfo.packageName)));}}
 @Test public void falseTorrentMimeAndExtensionDoNotPopulateDraft()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());f.context.startActivity(new Intent().setComponent(new ComponentName(f.pkg+".test","hu.synostream.android.FixtureTorrentSender")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("kind","invalid").putExtra("share",false));assertTrue(f.device.wait(Until.hasObject(By.text("Új torrent")),10000));f.instrumentation.waitForIdleSync();CountDownLatch drained=new CountDownLatch(1);f.app.cacheIo.execute(()->f.app.main.post(drained::countDown));assertTrue(drained.await(10,TimeUnit.SECONDS));assertEquals("A fájl nem érvényes torrent.",UiLocale.wrap(f.context).getString(R.string.invalid_torrent_content));assertTrue(f.app.torrentDraft.open);assertNull(f.app.torrentDraft.bytes);assertEquals("",f.app.torrentDraft.filename);assertEquals(0,n.prepares);assertEquals(0,n.starts);}}
 Object cacheLock()throws Exception{java.lang.reflect.Field field=SynoApp.class.getDeclaredField("cacheLock");field.setAccessible(true);return field.get(f.app);}
 @Test public void cacheLoadDoesNotBlockMainAndCancellationRejectsResult()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());JSONObject library=f.app.selected();Library.Card stored=new Library.Card("/Movies/Cached.mkv","Cached fixture",true);try(FileOutputStream out=new FileOutputStream(f.app.cacheFile(library))){out.write(new JSONArray().put(stored.json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}Object lock=cacheLock();CountDownLatch locked=new CountDownLatch(1),release=new CountDownLatch(1),heartbeat=new CountDownLatch(1),drained=new CountDownLatch(1);AtomicBoolean completed=new AtomicBoolean();Thread holder=new Thread(()->{synchronized(lock){locked.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}}});holder.start();assertTrue(locked.await(3,TimeUnit.SECONDS));try{f.app.main.post(()->{f.app.loadCache(library,()->completed.set(true));f.app.main.post(heartbeat::countDown);});assertTrue("Disk lock must not block the main thread",heartbeat.await(3,TimeUnit.SECONDS));Library.Card current=new Library.Card("/Movies/Current.mkv","Current fixture",true);f.instrumentation.runOnMainSync(()->{assertEquals("Korábbi lista betöltése…",f.app.status);f.app.cancelScan();f.app.rawCards=new ArrayList<>(List.of(current));f.app.cards=new ArrayList<>(List.of(current));});release.countDown();f.app.cacheIo.execute(()->f.app.main.post(drained::countDown));assertTrue(drained.await(10,TimeUnit.SECONDS));assertTrue(completed.get());assertFalse(f.app.busy);assertTrue(f.app.rawCards.isEmpty());assertTrue(f.app.cards.isEmpty());assertEquals("",f.app.status);}finally{release.countDown();holder.join(3000);}}}
 @Test public void warmCacheIsAppliedBeforeDecidingWhetherToScan()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());JSONObject library=f.app.selected();Library.Card stored=new Library.Card("/Movies/Cached.mkv","Cached fixture",true);try(FileOutputStream out=new FileOutputStream(f.app.cacheFile(library))){out.write(new JSONArray().put(stored.json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}n.holdListResponse=true;MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->activity.select(library));long end=System.currentTimeMillis()+10000;while(f.app.busy&&System.currentTimeMillis()<end)Thread.sleep(25);assertFalse(f.app.busy);assertEquals("Cached fixture",f.app.cards.get(0).title);assertFalse(f.app.scanRunning);assertEquals(1,n.listRequestRead.getCount());}}
 @Test public void absentCacheStartsScanOnlyAfterCacheWorkerCompletes()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());JSONObject library=f.app.selected();f.app.removeCache(library);n.holdListResponse=true;CountDownLatch workerEntered=new CountDownLatch(1),release=new CountDownLatch(1);f.app.cacheIo.execute(()->{workerEntered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(workerEntered.await(3,TimeUnit.SECONDS));try{MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->activity.select(library));assertEquals("Korábbi lista betöltése…",f.app.status);assertFalse(f.app.scanRunning);assertEquals(1,n.listRequestRead.getCount());release.countDown();assertTrue(n.listRequestRead.await(10,TimeUnit.SECONDS));n.releaseListResponse.countDown();long end=System.currentTimeMillis()+20000;while(f.app.busy&&System.currentTimeMillis()<end)Thread.sleep(50);assertFalse(f.app.busy);assertEquals(2,f.app.rawCards.size());}finally{release.countDown();n.releaseListResponse.countDown();}}}
}
